import { ChevronDownIcon } from '@heroicons/react/24/outline'
import React from 'react'

//////////////////same as caert.js
// import {
//   increment,
//   incrementAsync,
//   selectCount,
// } from './cartSlice';
import { Dialog, DialogBackdrop, DialogPanel, DialogTitle } from '@headlessui/react'
import { XMarkIcon } from '@heroicons/react/24/outline'
import { useState } from 'react';
import { Link, Navigate } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { delectItemfromCartAsync, selectItems, updateCartAsync } from '../features/cart/cartSlice';
import { set, useForm } from 'react-hook-form';
import { updateUserAsync } from '../features/user/userSlice';
import { createOrderAsync, selectCurrentOrder, selectCurrentOrderStatus } from '../features/order/orderSlice';
import { selectUserInfo } from '../features/user/userSlice';
import { discountedPrice } from '../app/constants';

///////////////////////




function Checkout() {
    /////// it copy form cart.js ///
    // const products = [
    //     {
    //         id: 1,
    //         name: 'Throwback Hip Bag',
    //         href: '#',
    //         color: 'Salmon',
    //         price: '$90.00',
    //         quantity: 1,
    //         imageSrc: 'https://tailwindcss.com/plus-assets/img/ecommerce-images/shopping-cart-page-04-product-01.jpg',
    //         imageAlt: 'Salmon orange fabric pouch with match zipper, gray zipper pull, and adjustable hip belt.',
    //     },
    //     {
    //         id: 2,
    //         name: 'Medium Stuff Satchel',
    //         href: '#',
    //         color: 'Blue',
    //         price: '$32.00',
    //         quantity: 1,
    //         imageSrc: 'https://tailwindcss.com/plus-assets/img/ecommerce-images/shopping-cart-page-04-product-02.jpg',
    //         imageAlt:
    //             'Front of satchel with blue canvas body, black straps and handle, drawstring top, and front zipper pouch.',
    //     },
    //     {
    //         id: 3,
    //         name: 'Zip Tote Basket',
    //         href: '#',
    //         color: 'White and black',
    //         price: '$140.00',
    //         quantity: 1,
    //         imageSrc: 'https://tailwindcss.com/plus-assets/img/ecommerce-images/shopping-cart-page-04-product-03.jpg',
    //         imageAlt: 'Front of zip tote bag with white canvas, black canvas straps and handle, and black zipper pulls.',
    //     },
    // ]
    const dispatch = useDispatch();

    const {
        register,
        handleSubmit,
        reset,//////// it is for checkout page reset button
        formState: { errors }
    } = useForm();


    const user = useSelector(selectUserInfo)
    console.log("userdata", user);

    //////////////////////////////////////////////////////////////////////////////
    const currentOrder = useSelector(selectCurrentOrder)

    const [open, setOpen] = useState(true)
    ////////////////////////////////////////////
    const addresses = [
        {
            name: 'Leslie Alexander',
            Society: 'elegance',
            Society_no: "A-201",
            pin_code: "392254",
            area: "mota varachha",
            city: "surat",
        },
    ]


    //////////////////////////////////////////////////////////////////////////////
    const items = useSelector(selectItems);  ///for fetch a data 

    const totalAmount = items.reduce(
        (amount, item) => discountedPrice(item.product) * item.quantity + amount, 0)

    const totalItems = items.reduce((total, item) => item.quantity + total, 0)

    const [selectedAddress, setselectedAddress] = useState(null)
    const [paymentMethod, setpaymentMethod] = useState('cash')


    const handleQuantity = (e, item) => {
        dispatch(updateCartAsync({ id: item.id, quantity: +e.target.value }))
    }

    const handleRemove = (e, id) => {
        dispatch(delectItemfromCartAsync(id))
    }



    /////address
    const handleAddress = (e) => {
        console.log(e.target.value);

        setselectedAddress(user.addresses[e.target.value])
        console.log(user.addresses[e.target.value])

    }
    const handlePayment = (e) => {
        console.log(e.target.value);

        setpaymentMethod(e.target.value);
    }

    ////////////oder button
    //////////makr api ,slice,order.js 
    const handleOrder = (e) => {
        // console.log(e.target.value);
        if (selectedAddress && paymentMethod) {


            const order = {
                items,
                totalAmount,
                totalItems,
                user: user.id,
                paymentMethod,
                selectedAddress,
                status: 'pending'//  statu change hokta hai jab apke when your product dipatch or deliverd or received 
            }
            console.log(order);

            dispatch(createOrderAsync(order))

            /// need to redirect from here to a new page of order success 
        } else {
            /// TODO: we can uses proper messaging popoup here
            alert('Enter Address and Payment method')
            // TODO:redirect to order-success page
            ////TODO :clear cart after order 
            // TODO :on  server change the stock number of items
        }
    }

    return (
        <>
            {!items.length && <Navigate to='/' replace={true}></Navigate>}
            {/* ///// navigate is use when the cart is empty then it leave or exist the checkout page */}
            {currentOrder && currentOrder.paymentMethod === 'cash' &&
                (<Navigate to={`/order-success/${currentOrder.id}`} replace={true}></Navigate>)
            }

            {currentOrder && currentOrder.paymentMethod === 'card' &&
                (<Navigate to={`/stripe-checkout/`} replace={true}></Navigate>)
            }



            <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 bg-slate-200">

                <div className="grid grid-cols-1 gap-x-8 gap-y-10 lg:grid-cols-5 pt-5">
                    <div className="lg:col-span-3 ">

                        <form className="bg-gray-100 px-5  py-9"

                            noValidate
                            onSubmit={handleSubmit((data) => {
                                // console.log(data);
                                // console.log(user);
                                // console.log("user =", user);
                                // console.log("addresses =", user?.addresses);



                                dispatch(
                                    // loginUserAsync({ email: data.email, password: data.password })

                                    updateUserAsync({ ...user, addresses: [...user.addresses, data] })///////////////////////////////////add address page of shopping icon checkout 
                                );

                                reset();
                                console.log(data); ////novalidyion mean that html ka validation bich me nahi    ayega

                            })}



                        >
                            <div className="space-y-12 shadow-black">

                                <div className="border-b border-gray-900/10 pb-12">
                                    <h2 className="text-base/7 font-bold text-black ">Personal Information</h2>
                                    <p className="mt-1 text-sm/6 text-black">Use a permanent address where you can receive mail.</p>

                                    <div className="mt-10 grid grid-cols-1 gap-x-6 gap-y-8 sm:grid-cols-6">
                                        <div className="sm:col-span-3">
                                            <label htmlFor="name" className="block text-sm/6 font-medium text-black">
                                                Full name
                                            </label>
                                            <div className="mt-2">
                                                <input
                                                    id="name"
                                                    {...register('name', { required: 'name is required' })}
                                                    type="text"
                                                    autoComplete="given-name"
                                                    className="block w-full rounded-md bg-white/5 px-3 py-1.5 text-base text-black outline-1 -outline-offset-1 outline-white/10 placeholder:text-gray-500 focus:outline-2 focus:-outline-offset-2 focus:outline-indigo-500 sm:text-sm/6"
                                                />
                                            </div>
                                        </div>



                                        <div className="sm:col-span-4">
                                            <label htmlFor="email" className="block text-sm/6 font-medium text-black">
                                                Email address
                                            </label>
                                            <div className="mt-2">
                                                <input
                                                    id="email"
                                                    {...register('email', { required: 'email is required' })}
                                                    type="email"
                                                    className="block w-full rounded-md bg-white/5 px-3 py-1.5 text-base text-black outline-1 -outline-offset-1 outline-white/10 placeholder:text-gray-500 focus:outline-2 focus:-outline-offset-2 focus:outline-indigo-500 sm:text-sm/6"
                                                />
                                            </div>
                                        </div>

                                        <div className="sm:col-span-3">
                                            <label htmlFor="country" className="block text-sm/6 font-medium text-black">
                                                Phone
                                            </label>
                                            <div className="mt-2 grid grid-cols-1">
                                                <input
                                                    id="phone"
                                                    {...register('phone', { required: 'phone is required' })}
                                                    type="tel"
                                                    className="block w-full rounded-md bg-white/5 px-3 py-1.5 text-base text-black outline-1 -outline-offset-1 outline-white/10 placeholder:text-gray-500 focus:outline-2 focus:-outline-offset-2 focus:outline-indigo-500 sm:text-sm/6"
                                                />
                                                <ChevronDownIcon
                                                    aria-hidden="true"
                                                    className="pointer-events-none col-start-1 row-start-1 mr-2 size-5 self-center justify-self-end text-black sm:size-4"
                                                />
                                            </div>
                                        </div>

                                        <div className="col-span-full">
                                            <label htmlFor="street" className="block text-sm/6 font-medium text-black">
                                                Street
                                            </label>
                                            <div className="mt-2">
                                                <input
                                                    id="street"
                                                    {...register('street', { required: 'street is required' })}
                                                    type="text"
                                                    className="block w-full rounded-md bg-white/5 px-3 py-1.5 text-base text-black outline-1 -outline-offset-1 outline-white/10 placeholder:text-gray-500 focus:outline-2 focus:-outline-offset-2 focus:outline-indigo-500 sm:text-sm/6"
                                                />
                                            </div>
                                        </div>

                                        <div className="sm:col-span-2 sm:col-start-1">
                                            <label htmlFor="city" className="block text-sm/6 font-medium text-black">
                                                City
                                            </label>
                                            <div className="mt-2">
                                                <input
                                                    id="city"
                                                    {...register('city', { required: 'city is required' })}
                                                    type="text"
                                                    className="block w-full rounded-md bg-white/5 px-3 py-1.5 text-base text-black outline-1 -outline-offset-1 outline-white/10 placeholder:text-gray-500 focus:outline-2 focus:-outline-offset-2 focus:outline-indigo-500 sm:text-sm/6"
                                                />
                                            </div>
                                        </div>

                                        <div className="sm:col-span-2">
                                            <label htmlFor="state" className="block text-sm/6 font-medium text-black">
                                                State / Province
                                            </label>
                                            <div className="mt-2">
                                                <input
                                                    id="state"
                                                    {...register('state', { required: 'state is required' })}
                                                    type="text"
                                                    className="block w-full rounded-md bg-white/5 px-3 py-1.5 text-base text-black outline-1 -outline-offset-1 outline-white/10 placeholder:text-gray-500 focus:outline-2 focus:-outline-offset-2 focus:outline-indigo-500 sm:text-sm/6"
                                                />
                                            </div>
                                        </div>

                                        <div className="sm:col-span-2">
                                            <label htmlFor="pincode" className="block text-sm/6 font-medium text-black">
                                                ZIP / Postal code
                                            </label>
                                            <div className="mt-2">
                                                <input
                                                    id="pincode"
                                                    {...register('pincode', { required: 'pincode is required' })}
                                                    type="text"
                                                    autoComplete="pincode"
                                                    className="block w-full rounded-md bg-white/5 px-3 py-1.5 text-base text-black outline-1 -outline-offset-1 outline-white/10 placeholder:text-gray-500 focus:outline-2 focus:-outline-offset-2 focus:outline-indigo-500 sm:text-sm/6"
                                                />
                                            </div>
                                        </div>
                                    </div>
                                </div>
                                <div className="border-b border--gray-900/10 pb-12">
                                    {/* //////////////////////////////////////////// */}
                                    <div className="mt-6 flex items-center justify-end gap-x-6">
                                        <button type="button" className="text-sm/6 font-semibold text-gray-600">
                                            Reset
                                        </button>
                                        <button
                                            type="submit"
                                            className="rounded-md bg-indigo-500 px-3 py-2 text-sm font-semibold text-white focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-500"
                                        >
                                            Add Address
                                        </button>
                                    </div>

                                    <h2 className="text-base/7 font-semibold text-black">Address</h2>
                                    <p className="mt-1 text-sm/6 text-black">
                                        We'll always let you know about important changes, but you pick what else you want to hear about.
                                    </p>
                                    <ul role="list" className="divide-y divide-white/5 bg-white" >
                                        {
                                            user.addresses && user.addresses.map((address, index) => (

                                                <li
                                                    key={index}
                                                    className="flex justify-between gap-x-6 py-5">


                                                    <div className="flex min-w-0 gap-x-4">
                                                        <input
                                                            onChange={handleAddress}
                                                            name='address'
                                                            type="radio"
                                                            value={index}
                                                            className='h-4 w-4 border-gray-400 text-indigo-600 focus:ring-indigo-600 '
                                                        />



                                                        <div className="min-w-0 flex-auto pl-4">
                                                            <p className="text-sm/6 font-semibold text-black">{address.name}</p>
                                                            <p className="mt-1 truncate text-xs/5 text-gray-400">{address.Society}</p>
                                                            <p className="mt-1 truncate text-xs/5 text-gray-400">{address.phone}</p>
                                                            <p className="mt-1 truncate text-xs/5 text-gray-400">{address.email}</p>
                                                            <p className="mt-1 truncate text-xs/5 text-gray-400">{address.pincode}</p>





                                                        </div>
                                                    </div>
                                                    <div className="hidden shrink-0 sm:flex sm:flex-col sm:items-end pr-4 text-sm pt-5">
                                                        <p className="mt-1 truncate text-xs/5 text-gray-400">{address.street}</p>
                                                        <p className="mt-1 truncate text-xs/5 text-gray-400">{address.city}</p>
                                                        <p className="mt-1 truncate text-xs/5 text-gray-400">{address.state}</p>



                                                    </div>
                                                </li>
                                            ))}
                                    </ul>



                                    {/* /////////////////////////// */}

                                    <div className="mt-10 space-y-10">
                                        <fieldset>
                                            <legend className="text-sm/6 font-semibold text-black">Payment method</legend>
                                            <p className="mt-1 text-sm/6 text-black">Choose One</p>
                                            <div className="mt-6 space-y-6">
                                                <div className="flex items-center gap-x-3">
                                                    <input
                                                        id="cash"
                                                        onChange={handlePayment}
                                                        name="payments"
                                                        value="cash"
                                                        type="radio"
                                                        checked={paymentMethod === "cash"}
                                                        className="relative size-4 appearance-none rounded-full border border-gray-600 bg-white/5 before:absolute before:inset-1 before:rounded-full before:bg-white not-checked:before:hidden checked:border-indigo-500 checked:bg-indigo-500 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-500 disabled:border-white/5 disabled:bg-white/10 disabled:before:bg-white/20 forced-colors:appearance-auto forced-colors:before:hidden"
                                                    />
                                                    <label htmlFor="push-everything" className="block text-sm/6 font-medium text-black">
                                                        Cash on delivery
                                                    </label>
                                                </div>
                                                <div className="flex items-center gap-x-3">
                                                    <input
                                                        id="card"
                                                        onChange={handlePayment}
                                                        name="payments"
                                                        value="card"
                                                        type="radio"
                                                        checked={paymentMethod === "card"}

                                                        className="relative size-4 appearance-none rounded-full border border-gray-600 bg-white/5 before:absolute before:inset-1 before:rounded-full before:bg-white not-checked:before:hidden checked:border-indigo-500 checked:bg-indigo-500 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-500 disabled:border-white/5 disabled:bg-white/10 disabled:before:bg-white/20 forced-colors:appearance-auto forced-colors:before:hidden"
                                                    />
                                                    <label htmlFor="push-email" className="block text-sm/6 font-medium text-black">
                                                        Online Payment
                                                    </label>
                                                </div>

                                            </div>
                                        </fieldset>
                                    </div>
                                </div>



                            </div>
                        </form>
                    </div>


                    {/* /////same copy form cart/// */}
                    <div className="lg:col-span-2">
                        <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-  bg-white shadow-lg">

                            <div className="border-t border-gray-200 px-4 py-6 sm:px-0">
                                <h1 className="text-4xl font-bold tracking-tight text-gray-900 pb-5">Cart</h1>

                                <div className="flow-root">
                                    <ul role="list" className="-my-6 divide-y divide-gray-200">
                                        {items.map((item) => (
                                            <li key={item.id} className="flex py-6">
                                                <div className="size-24 shrink-0 overflow-hidden rounded-md border border-gray-200">
                                                    <img alt={item.product.title} src={item.product.thumbnail} className="size-full object-cover" />
                                                </div>

                                                <div className="ml-4 flex flex-1 flex-col">
                                                    <div>
                                                        <div className="flex justify-between text-base font-medium text-gray-900">
                                                            <h3>
                                                                <a href={item.category}>{item.product.brand}</a>
                                                            </h3>
                                                            <p className="ml-4">${discountedPrice(item.product)}</p>
                                                        </div>
                                                        <h3>
                                                            <a className="mt-1 text-sm text-gray-500" href={item.product.id}>{item.product.title}</a>
                                                        </h3>
                                                    </div>
                                                    <div className="flex flex-1 items-end justify-between text-sm">
                                                        <p className="text-gray-500 ">
                                                            <label htmlFor="Quantity"
                                                                className="inline me-4 text-sm/6 font-medium text-black">
                                                                Qty
                                                            </label>
                                                            <select onChange={(e) => handleQuantity(e, item)} value={item.quantity}
                                                            // value={item.quantity}
                                                            >
                                                                <option value="1">1</option>
                                                                <option value="2">2</option>
                                                                <option value="3">3</option>
                                                                <option value="4">4</option>
                                                                <option value="5">5</option>
                                                            </select>

                                                        </p>

                                                        <div className="flex">
                                                            <button
                                                                onClick={e => handleRemove(e, item.id)}
                                                                type="button"
                                                                className="font-medium text-indigo-600 hover:text-indigo-500">
                                                                Remove
                                                            </button>
                                                        </div>
                                                    </div>
                                                </div>
                                            </li>
                                        ))}
                                    </ul>
                                </div>
                            </div>


                            <div className="border-t border-gray-200 px-4 py-6 sm:px-6 bg-white">
                                <div className="flex justify-between my-2 text-base font-medium text-gray-900">
                                    <p>Subtotal</p>
                                    <p>${totalAmount}</p>

                                    {/* <p>$262.00</p> */}
                                </div>
                                <div className="flex justify-between  my-2 text-base font-medium text-gray-900">
                                    <p>total items in Cart</p>
                                    <p>{totalItems} items</p>

                                    {/* <p>$262.00</p> */}
                                </div>

                                <p className="mt-0.5 text-sm text-gray-500">Shipping and taxes calculated at checkout.</p>
                                <div className="mt-6">
                                    <Link
                                    //  to={'/Order-success/:id'}   
                                    >
                                        <div
                                            // /////
                                            onClick={handleOrder}
                                            className="flex items-center cursor-pointer justify-center rounded-md border border-transparent bg-indigo-600 px-6 py-3 text-base font-medium text-white shadow-xs hover:bg-indigo-700"
                                        >
                                            Order Now
                                        </div>
                                    </Link>
                                </div>
                                <div className="mt-6 flex justify-center text-center text-sm text-gray-500">
                                    <p>
                                        or{' '}
                                        <Link to={'/'}>
                                            <button
                                                type="button"
                                                onClick={() => setOpen(false)}
                                                className="font-medium text-indigo-600 hover:text-indigo-500"
                                            >
                                                Continue Shopping
                                                <span aria-hidden="true"> &rarr;</span>
                                            </button>
                                        </Link>
                                    </p>
                                </div>
                            </div>
                        </div>
                    </div>
                    {/* ////////////////////////////////////  */}

                </div>
            </div>
        </>
    )
}

export default Checkout