import React, { useEffect } from 'react'

import { PhotoIcon, UserCircleIcon } from '@heroicons/react/24/solid'
import { ChevronDownIcon } from '@heroicons/react/16/solid'
import { clearSelectedProduct, createProductAsync, fetchProductByIdAsync, selectBrand, selectCategories, selectedProductById, updateProductAsync } from '../../product/productListSlice';
import { useDispatch, useSelector } from 'react-redux';
import { useForm } from 'react-hook-form';
import { useParams } from 'react-router-dom';
import { updateCartAsync } from '../../cart/cartSlice';
import { resetCart } from '../../cart/cartAPI';
// import { useAlert } from 'react-alert';
function ProductForm() {
    const {
        register,
        handleSubmit,
        setValue,
        reset,
        formState: { errors } } = useForm();



    const categories = useSelector(selectCategories);
    const brands = useSelector(selectBrand);
    const dispatch = useDispatch()
    const params = useParams()
    const selectedProduct = useSelector(selectedProductById)
    // const alert = useAlert()

    useEffect(() => {

        if (params.id) {

            dispatch(fetchProductByIdAsync(params.id))
            // setValue("title", product.name)

        } else {
            dispatch(clearSelectedProduct())
        }

    }, [params.id, dispatch])

    useEffect(() => {
        if (selectedProduct && params.id) {

            setValue("title", selectedProduct.title)
            setValue("description", selectedProduct.description)
            setValue("price", selectedProduct.price)
            setValue("discountPercentage", selectedProduct.discountPercentage)
            setValue("thumbnail", selectedProduct.thumbnail)
            setValue("stock", selectedProduct.stock)
            setValue("brand", selectedProduct.brand)
            setValue("category", selectedProduct.category)
            setValue("image1", selectedProduct.images[0]);
            setValue("image2", selectedProduct.images[1]);
            setValue("image3", selectedProduct.images[2]);

        }

    }, [selectedProduct, params.id, setValue])
    const handleDelete = () => {
        const product = { ...selectedProduct };
        product.deleted = true;
        dispatch(updateProductAsync(product))
    }


    return (
        <form
            noValidate
            onSubmit={handleSubmit((data) => {
                console.log(data);
                const product = { ...data }
                product.images = [product.image1, product.image2, product.image3, product.thumbnail]

                product.rating = 0
                delete product["image1"]
                delete product["image2"]
                delete product["image3"]
                product.price = +product.price;
                product.discountPercentage = +product.discountPercentage;
                product.stock = +product.stock;

                console.log(product);
                // dispatch(createProductAsync(product))

                if (params.id) {
                    product.id = params.id
                    product.rating = selectedProduct.rating || 0;
                    dispatch(updateProductAsync(product))
                    alert.success('Product updated')
                    reset();

                } else {
                    dispatch(createProductAsync(product))
                    alert.success('Product created')
                    // TODO: these alerts should check if API failed 

                    reset();

                }


            })}
        >
            <div className="space-y-12 p-2">
                <div className="border-b border-white/10 pb-12">
                    <h2 className="text-base/7 font-semibold text-white">Add Product</h2>
                    <p className="mt-1 text-sm/6 text-gray-400">
                        This information will be displayed publicly so be careful what you share.
                    </p>

                    <div className="mt-10 grid grid-cols-1 gap-x-6 gap-y-8 sm:grid-cols-6">
                        <div className="sm:col-span-4">
                            <label htmlFor="title" className="block text-sm/6 font-medium text-white">
                                Product Name
                            </label>
                            <div className="mt-2">
                                <div className="flex items-center rounded-md bg-white/5 outline-1 -outline-offset-1 outline-white/10 focus-within:outline-2 focus-within:-outline-offset-2 focus-within:outline-indigo-500">

                                    <input
                                        id="title"
                                        {...register('title', {
                                            required: "name is required",
                                        }
                                        )}
                                        type="text"
                                        // placeholder="Enter name"
                                        className="block min-w-0 grow bg-transparent py-1.5 pr-3 pl-1 text-base text-white placeholder:text-gray-500 focus:outline-none sm:text-sm/6"
                                    />
                                </div>
                            </div>
                        </div>
                        {/* /////////////discription */}
                        <div className="col-span-full">
                            <label htmlFor="description" className="block text-sm/6 font-medium text-white">
                                Description
                            </label>
                            <div className="mt-2">
                                <textarea
                                    id="description"
                                    {...register('description', {
                                        required: "description is required",
                                    }
                                    )}
                                    rows={3}
                                    className="block w-full rounded-md bg-white/5 px-3 py-1.5 text-base text-white outline-1 -outline-offset-1 outline-white/10 placeholder:text-gray-500 focus:outline-2 focus:-outline-offset-2 focus:outline-indigo-500 sm:text-sm/6"
                                    defaultValue={''}
                                />
                            </div>
                            <p className="mt-3 text-sm/6 text-gray-400">Write a few sentences About Product.</p>
                        </div>
                        {/* //////////////////////brand */}
                        <div className="col-span-full">
                            <label htmlFor="brand" className="block text-sm/6 font-medium text-white">
                                Brand
                            </label>
                            <div className="mt-2">
                                <select {...register('brand', {
                                    required: "brand is required",
                                }
                                )}
                                >
                                    <option value="" className='font-thin'>---Choose Brand---</option>
                                    {brands.map((brand) =>
                                        <option value={brand.value}>{brand.label}</option>

                                    )}
                                </select>
                            </div>
                            <p className="mt-3 text-sm/6 text-gray-400">Write a few sentences About Product.</p>
                        </div>
                        {/* ///////////category///*/}

                        <div className="col-span-full">
                            <label htmlFor="category" className="block text-sm/6 font-medium text-white">
                                Category
                            </label>
                            <div className="mt-2">
                                <select
                                    {...register('category', {
                                        required: "category is required",
                                    }
                                    )}
                                >
                                    <option value="" className='font-thin'>---Choose Category---</option>
                                    {categories.map((category) =>
                                        <option value={category.value}>{category.label}</option>

                                    )}
                                </select>
                            </div>
                            <p className="mt-3 text-sm/6 text-gray-400">Write a few sentences About Product.</p>
                        </div>


                        {/* /////////price */}
                        <div className="sm:col-span-1">
                            <label htmlFor="price" className="block text-sm/6 font-medium text-white">
                                Price
                            </label>
                            <div className="mt-2">
                                <div className="flex items-center rounded-md bg-white/5 outline-1 -outline-offset-1 outline-white/10 focus-within:outline-2 focus-within:-outline-offset-2 focus-within:outline-indigo-500">

                                    <input
                                        id="price"
                                        {...register('price', {
                                            required: "price is required",
                                            min: 1,
                                            max: 1000,
                                        }
                                        )} type="number"
                                        // placeholder="Enter name"
                                        className="block min-w-0 grow bg-transparent py-1.5 pr-3 pl-1 text-base text-white placeholder:text-gray-500 focus:outline-none sm:text-sm/6"
                                    />
                                </div>
                            </div>
                        </div>

                        {/* ////////////////////discount */}
                        <div className="sm:col-span-1">
                            <label htmlFor="discountPercentage" className="block text-sm/6 font-medium text-white">
                                Discount Percentage
                            </label>
                            <div className="mt-2">
                                <div className="flex items-center rounded-md bg-white/5 outline-1 -outline-offset-1 outline-white/10 focus-within:outline-2 focus-within:-outline-offset-2 focus-within:outline-indigo-500">

                                    <input
                                        id="discountPercentage"
                                        {...register('discountPercentage', {
                                            required: "discountPercentage is required",
                                            min: 0,
                                            max: 100,
                                        }
                                        )} type="number"
                                        // placeholder="Enter name"
                                        className="block min-w-0 grow bg-transparent py-1.5 pr-3 pl-1 text-base text-white placeholder:text-gray-500 focus:outline-none sm:text-sm/6"
                                    />
                                </div>
                            </div>
                        </div>
                        {/* ///////////////////stock */}
                        <div className="sm:col-span-1">
                            <label htmlFor="stock" className="block text-sm/6 font-medium text-white">
                                Stock
                            </label>
                            <div className="mt-2">
                                <div className="flex items-center rounded-md bg-white/5 outline-1 -outline-offset-1 outline-white/10 focus-within:outline-2 focus-within:-outline-offset-2 focus-within:outline-indigo-500">

                                    <input
                                        id="stock"
                                        {...register('stock', {
                                            required: "stock is required",
                                            min: 0,
                                        }
                                        )} type="number"
                                        // placeholder="Enter name"
                                        className="block min-w-0 grow bg-transparent py-1.5 pr-3 pl-1 text-base text-white placeholder:text-gray-500 focus:outline-none sm:text-sm/6"
                                    />
                                </div>
                            </div>
                        </div>

                        {/* //////////////////thumbnail */}
                        <div className="sm:col-span-4">
                            <label htmlFor="thumbnail" className="block text-sm/6 font-medium text-white">
                                Thumbnail
                            </label>
                            <div className="mt-2">
                                <div className="flex items-center rounded-md bg-white/5 outline-1 -outline-offset-1 outline-white/10 focus-within:outline-2 focus-within:-outline-offset-2 focus-within:outline-indigo-500">

                                    <input
                                        id="thumbnail"
                                        {...register('thumbnail', {
                                            required: "thumbnail is required",
                                        }
                                        )} type="text"
                                        // placeholder="Enter name"
                                        className="block min-w-0 grow bg-transparent py-1.5 pr-3 pl-1 text-base text-white placeholder:text-gray-500 focus:outline-none sm:text-sm/6"
                                    />
                                </div>
                            </div>
                        </div>
                        {/* ////////    */}
                        <div className="sm:col-span-4">
                            <label htmlFor="image1" className="block text-sm/6 font-medium text-white">
                                Image 1
                            </label>
                            <div className="mt-2">
                                <div className="flex items-center rounded-md bg-white/5 outline-1 -outline-offset-1 outline-white/10 focus-within:outline-2 focus-within:-outline-offset-2 focus-within:outline-indigo-500">

                                    <input
                                        id="image1"
                                        {...register('image1', {
                                            required: "image  is required",
                                        }
                                        )}
                                        type="text"
                                        // placeholder="Enter name"
                                        className="block min-w-0 grow bg-transparent py-1.5 pr-3 pl-1 text-base text-white placeholder:text-gray-500 focus:outline-none sm:text-sm/6"
                                    />
                                </div>
                            </div>
                        </div>

                        <div className="sm:col-span-4">
                            <label htmlFor="image2" className="block text-sm/6 font-medium text-white">
                                Image 2
                            </label>
                            <div className="mt-2">
                                <div className="flex items-center rounded-md bg-white/5 outline-1 -outline-offset-1 outline-white/10 focus-within:outline-2 focus-within:-outline-offset-2 focus-within:outline-indigo-500">

                                    <input
                                        id="image2"
                                        {...register('image2', {
                                            required: "image is required",
                                        }
                                        )} type="text"
                                        // placeholder="Enter name"
                                        className="block min-w-0 grow bg-transparent py-1.5 pr-3 pl-1 text-base text-white placeholder:text-gray-500 focus:outline-none sm:text-sm/6"
                                    />
                                </div>
                            </div>
                        </div>
                        <div className="sm:col-span-4">
                            <label htmlFor="image3" className="block text-sm/6 font-medium text-white">
                                Image 3
                            </label>
                            <div className="mt-2">
                                <div className="flex items-center rounded-md bg-white/5 outline-1 -outline-offset-1 outline-white/10 focus-within:outline-2 focus-within:-outline-offset-2 focus-within:outline-indigo-500">

                                    <input
                                        id="image3"
                                        {...register('image3', {
                                            required: "image is required",
                                        }
                                        )} type="text"
                                        // placeholder="Enter name"
                                        className="block min-w-0 grow bg-transparent py-1.5 pr-3 pl-1 text-base text-white placeholder:text-gray-500 focus:outline-none sm:text-sm/6"
                                    />
                                </div>
                            </div>
                        </div>










                    </div>
                </div>



                <div className="border-b border-white/10 pb-12">
                    <h2 className="text-base/7 font-semibold text-white">Extra</h2>


                    <div className="mt-10 space-y-10">
                        <fieldset>
                            <legend className="text-sm/6 font-semibold text-white">By email</legend>
                            <div className="mt-6 space-y-6">
                                <div className="flex gap-3">
                                    <div className="flex h-6 shrink-0 items-center">
                                        <div className="group grid size-4 grid-cols-1">
                                            <input
                                                defaultChecked
                                                id="comments"
                                                name="comments"
                                                type="checkbox"
                                                aria-describedby="comments-description"
                                                className="col-start-1 row-start-1 appearance-none rounded-sm border border-white/10 bg-white/5 checked:border-indigo-500 checked:bg-indigo-500 indeterminate:border-indigo-500 indeterminate:bg-indigo-500 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-500 disabled:border-white/5 disabled:bg-white/10 disabled:checked:bg-white/10 forced-colors:appearance-auto"
                                            />
                                            <svg
                                                fill="none"
                                                viewBox="0 0 14 14"
                                                className="pointer-events-none col-start-1 row-start-1 size-3.5 self-center justify-self-center stroke-white group-has-disabled:stroke-white/25"
                                            >
                                                <path
                                                    d="M3 8L6 11L11 3.5"
                                                    strokeWidth={2}
                                                    strokeLinecap="round"
                                                    strokeLinejoin="round"
                                                    className="opacity-0 group-has-checked:opacity-100"
                                                />
                                                <path
                                                    d="M3 7H11"
                                                    strokeWidth={2}
                                                    strokeLinecap="round"
                                                    strokeLinejoin="round"
                                                    className="opacity-0 group-has-indeterminate:opacity-100"
                                                />
                                            </svg>
                                        </div>
                                    </div>
                                    <div className="text-sm/6">
                                        <label htmlFor="comments" className="font-medium text-white">
                                            Comments
                                        </label>
                                        <p id="comments-description" className="text-gray-400">
                                            Get notified when someones posts a comment on a posting.
                                        </p>
                                    </div>
                                </div>
                                <div className="flex gap-3">
                                    <div className="flex h-6 shrink-0 items-center">
                                        <div className="group grid size-4 grid-cols-1">
                                            <input
                                                id="candidates"
                                                name="candidates"
                                                type="checkbox"
                                                aria-describedby="candidates-description"
                                                className="col-start-1 row-start-1 appearance-none rounded-sm border border-white/10 bg-white/5 checked:border-indigo-500 checked:bg-indigo-500 indeterminate:border-indigo-500 indeterminate:bg-indigo-500 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-500 disabled:border-white/5 disabled:bg-white/10 disabled:checked:bg-white/10 forced-colors:appearance-auto"
                                            />
                                            <svg
                                                fill="none"
                                                viewBox="0 0 14 14"
                                                className="pointer-events-none col-start-1 row-start-1 size-3.5 self-center justify-self-center stroke-white group-has-disabled:stroke-white/25"
                                            >
                                                <path
                                                    d="M3 8L6 11L11 3.5"
                                                    strokeWidth={2}
                                                    strokeLinecap="round"
                                                    strokeLinejoin="round"
                                                    className="opacity-0 group-has-checked:opacity-100"
                                                />
                                                <path
                                                    d="M3 7H11"
                                                    strokeWidth={2}
                                                    strokeLinecap="round"
                                                    strokeLinejoin="round"
                                                    className="opacity-0 group-has-indeterminate:opacity-100"
                                                />
                                            </svg>
                                        </div>
                                    </div>
                                    <div className="text-sm/6">
                                        <label htmlFor="candidates" className="font-medium text-white">
                                            Candidates
                                        </label>
                                        <p id="candidates-description" className="text-gray-400">
                                            Get notified when a candidate applies for a job.
                                        </p>
                                    </div>
                                </div>
                                <div className="flex gap-3">
                                    <div className="flex h-6 shrink-0 items-center">
                                        <div className="group grid size-4 grid-cols-1">
                                            <input
                                                id="offers"
                                                name="offers"
                                                type="checkbox"
                                                aria-describedby="offers-description"
                                                className="col-start-1 row-start-1 appearance-none rounded-sm border border-white/10 bg-white/5 checked:border-indigo-500 checked:bg-indigo-500 indeterminate:border-indigo-500 indeterminate:bg-indigo-500 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-500 disabled:border-white/5 disabled:bg-white/10 disabled:checked:bg-white/10 forced-colors:appearance-auto"
                                            />
                                            <svg
                                                fill="none"
                                                viewBox="0 0 14 14"
                                                className="pointer-events-none col-start-1 row-start-1 size-3.5 self-center justify-self-center stroke-white group-has-disabled:stroke-white/25"
                                            >
                                                <path
                                                    d="M3 8L6 11L11 3.5"
                                                    strokeWidth={2}
                                                    strokeLinecap="round"
                                                    strokeLinejoin="round"
                                                    className="opacity-0 group-has-checked:opacity-100"
                                                />
                                                <path
                                                    d="M3 7H11"
                                                    strokeWidth={2}
                                                    strokeLinecap="round"
                                                    strokeLinejoin="round"
                                                    className="opacity-0 group-has-indeterminate:opacity-100"
                                                />
                                            </svg>
                                        </div>
                                    </div>
                                    <div className="text-sm/6">
                                        <label htmlFor="offers" className="font-medium text-white">
                                            Offers
                                        </label>
                                        <p id="offers-description" className="text-gray-400">
                                            Get notified when a candidate accepts or rejects an offer.
                                        </p>
                                    </div>
                                </div>
                            </div>
                        </fieldset>

                    </div>
                </div>
            </div>

            <div className="mt-6 flex items-center justify-end gap-x-6">
                <button type="button" className="text-sm/6 font-semibold text-white">
                    Cancel
                </button>
                {selectedProduct && <button
                    onClick={handleDelete}
                    className="rounded-md bg-red-500 px-3 py-2 text-sm font-semibold text-white focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-500"
                >
                    Delete
                </button>}

                <button
                    type="submit"
                    className="rounded-md bg-indigo-500 px-3 py-2 text-sm font-semibold text-white focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-500"
                >
                    Save
                </button>
            </div>
        </form >
    )
}


export default ProductForm