import React, { useEffect, useState } from 'react'
import { discountedPrice, ITEM_PER_PAGE } from '../../../app/constants';
import { useDispatch, useSelector } from 'react-redux';
import { fetchAllOrdersAsync, selectOrders, selectTotalOrders, updateOrderAsync } from '../../order/orderSlice';
import { XMarkIcon, EyeIcon, PencilIcon, ArrowUpIcon, ArrowDownIcon } from '@heroicons/react/24/outline'
import Pagination from '../../common/Pagination';

function AdminOrders() {
    const dispatch = useDispatch();
    const orders = useSelector(selectOrders)
    const totalOrders = useSelector(selectTotalOrders)
    const [editableOrderId, setEditableOrderId] = useState(-1)
    const [sort, setSort] = useState({})

    const handleEdit = (order) => {
        setEditableOrderId(order.id)

    }

    const handleShow = () => {
        console.log("handleShow");
    }
    const handleUpdate = (e, order) => {
        const updatedOrder = { ...order, status: e.target.value }
        dispatch(updateOrderAsync(updatedOrder))
        setEditableOrderId(-1);

    }

    const chooseColor = (status) => {
        switch (status) {
            case 'pending':
                return 'bg-purple-200  text-purple-600';
            case 'dispatched':
                return 'bg-yellow-200  text-yellow-600';
            case 'Delivered':
                return 'bg-green-200  text-green-600';
            case 'Cancelled':
                return 'bg-red-200  text-red-600';
            default:
                return 'bg-red-200  text-red-600';
        }


    }

    const handlepage = (page) => {
        setPage(page);
        // const pagination = { _page: page, _limit: ITEM_PER_PAGE };
        // dispatch(fetchAllOrdersAsync(pagination));
    }

    const handleSort = (sortOption) => {
        const sort = { _sort: sortOption.sort, _order: sortOption.order }; ////// ,_ : it object,_order:option it string 
        console.log({ sort });
        setSort(sort)
    }



    const [page, setPage] = useState(1)
    useEffect(() => {
        const pagination = { _page: page, _limit: ITEM_PER_PAGE };
        dispatch(fetchAllOrdersAsync({ sort, pagination }));
    }, [dispatch, page, sort]);
    return (

        <>
            {/* Hello world */}
            <div className="bg-white p-8 rounded-md w-full">
                <div className=" flex items-center justify-between pb-6">
                    <div>
                        <h2 className="text-gray-600 font-semibold">Products Order</h2>
                        <span className="text-xs">All products item</span>
                    </div>
                    {/* <div className="flex items-center justify-between">
                        <div className="flex bg-gray-50 items-center p-2 rounded-md">
                            <svg
                                xmlns="http://www.w3.org/2000/svg"
                                className="h-5 w-5 text-gray-400"
                                viewBox="0 0 20 20"
                                fill="currentColor"
                            >
                                <path
                                    fillRule="evenodd"
                                    d="M8 4a4 4 0 100 8 4 4 0 000-8zM2 8a6 6 0 1110.89 3.476l4.817 4.817a1 1 0 01-1.414 1.414l-4.816-4.816A6 6 0 012 8z"
                                    clipRule="evenodd"
                                />
                            </svg>
                            <input
                                className="bg-gray-50 outline-none ml-1 block "
                                type="text"
                                name=""
                                id=""
                                placeholder="search..."
                            />
                        </div>
                        <div className="lg:ml-40 ml-10 space-x-8">
                            <button className="bg-indigo-600 px-4 py-2 rounded-md text-white font-semibold tracking-wide cursor-pointer">
                                New Report
                            </button>
                            <button className="bg-indigo-600 px-4 py-2 rounded-md text-white font-semibold tracking-wide cursor-pointer">
                                Create
                            </button>
                        </div>
                    </div> */}
                </div>
                <div>
                    <div className="-mx-4 sm:-mx-8 px-4 sm:px-8 py-4 overflow-x-auto">
                        <div className="inline-block min-w-full shadow rounded-lg overflow-hidden">
                            <table className="min-w-full leading-normal">
                                <thead>
                                    <tr>
                                        <th className="px-5 py-3 border-b-2 cursor-pointer border-gray-200 bg-gray-100 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider"
                                            onClick={(e) =>
                                                handleSort({
                                                    sort: 'id',
                                                    order: sort?._order === 'arc' ? 'desc' : 'asc',
                                                })}
                                        >
                                            Order # {''}
                                            {sort._sort === 'id' &&
                                                (sort._order === 'asc' ? (
                                                    <ArrowUpIcon className='w-4 h-4 inline'></ArrowUpIcon>)
                                                    : (<ArrowDownIcon className='w-4 h-4 inline'></ArrowDownIcon>)
                                                )}

                                        </th>
                                        <th className="px-5 py-3 border-b-2 border-gray-200 bg-gray-100 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">
                                            Items
                                        </th>
                                        {/* <th className="px-5 py-3 border-b-2 border-gray-200 bg-gray-100 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">
                                            Total Amount
                                        </th> */}
                                        <th className="px-5 py-3 border-b-2 cursor-pointer border-gray-200 bg-gray-100 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider"
                                            onClick={(e) =>
                                                handleSort({
                                                    sort: 'totalAmount',
                                                    order: sort?._order === 'arc' ? 'desc' : 'asc',
                                                })}
                                        >
                                            total Amount {''}
                                            {sort._sort === 'totalAmount' &&
                                                (sort._order === 'asc' ? (
                                                    <ArrowUpIcon className='w-4 h-4 inline'></ArrowUpIcon>)
                                                    : (<ArrowDownIcon className='w-4 h-4 inline'></ArrowDownIcon>)
                                                )}

                                        </th>




                                        <th className="px-5 py-3 border-b-2 border-gray-200 bg-gray-100 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">
                                            Shipping Address
                                        </th>

                                        <th className="px-5 py-3 border-b-2 border-gray-200 bg-gray-100 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">
                                            Status
                                        </th>
                                        <th className="px-5 py-3 border-b-2 border-gray-200 bg-gray-100 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">
                                            Actions
                                        </th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {orders.map(order => <tr>
                                        <td className="px-5 py-5 border-b border-gray-200 bg-white text-sm">
                                            <div className="flex items-center">
                                                <div className="ml-3">
                                                    <p className="text-gray-900 whitespace-no-wrap">
                                                        {order.id}
                                                    </p>
                                                </div>


                                            </div>
                                        </td>
                                        <td className="px-3 py-6 border-b border-gray-200 bg-white text-sm text-left">
                                            <p className="text-gray-900">
                                                {order.items.map(item => (<div className="flex items-center">
                                                    <img
                                                        className="w-14 h-12 rounded-full"
                                                        src={item.product.thumbnail}
                                                        alt=""
                                                    />

                                                    <p>{item.product.title} - Qty{item.quantity}- ${discountedPrice(item.product)}</p>

                                                </div>

                                                ))}

                                            </p>
                                        </td>
                                        <td className="px-5 py-5 border-b border-gray-200 bg-white text-sm">
                                            <p className="text-gray-900 whitespace-no-wrap">
                                                ${order.totalAmount}
                                            </p>
                                        </td>
                                        <td className="px-3 py-6 border-b border-gray-200 bg-white text-sm">
                                            <div className="text-gray-900 flex item-center justify-start font-semibold">
                                                <div className=""> <strong>{order.selectedAddress.name},</strong></div>
                                                <div>{order.selectedAddress.street},</div>
                                                <div>{order.selectedAddress.city},</div>
                                                <div>{order.selectedAddress.state},</div>
                                                <div>{order.selectedAddress.pincode},</div>
                                                <div>{order.selectedAddress.phone},</div>
                                            </div>
                                        </td>
                                        <td className="px-5 py-5 border-b border-gray-200 bg-white text-sm">
                                            {order.id === editableOrderId ? (
                                                <select onChange={e => handleUpdate(e, order)}>
                                                    <option value="pending">Pending</option>
                                                    <option value="dispatched">Dispatched</option>
                                                    <option value="Delivered">Delivered</option>
                                                    <option value="Cancelled ">Cancelled</option>
                                                </select>
                                            ) : (
                                                <span className={`${chooseColor(order.status)} py-1 px-3 rounded-full text-sm`}>
                                                    {order.status}
                                                </span>
                                            )}
                                        </td>




                                        <td className="px-5 py-5 border-b border-gray-200 bg-white text-sm">
                                            <span className="flex item-center justify-start font-semibold text-green-600 leading-tight">
                                                <span className='relative'>
                                                    <EyeIcon className='h-4 w-4 hover:text-green-900 mr-2' onClick={e => handleShow(order)}></EyeIcon></span>
                                                <span className='relative'>
                                                    <PencilIcon className='h-4 w-4 hover:text-green-900 mr-2' onClick={e => handleEdit(order)}> </PencilIcon></span>


                                            </span>
                                        </td>
                                    </tr>)}
                                </tbody>
                            </table>

                            <div className="px-5 py-5 bg-white border-t flex flex-col xs:flex-row items-center xs:justify-between">
                                <Pagination
                                    handlepage={handlepage}
                                    page={page}
                                    setPage={setPage}
                                    totalItem={totalOrders}
                                ></Pagination>
                            </div>
                        </div>
                    </div>
                </div>


            </div>
        </>


    )
}

export default AdminOrders