
import { BrowserRouter, Route, Routes } from 'react-router-dom';
import './App.css';
import Home from './pages/Home';
import LoginPage from './pages/LoginPage';
import SignupPage from './pages/SignupPage';
import CartPage from './pages/CartPage';
import Checkout from './pages/Checkout';
import ProductDetailPage from './pages/ProductDetailPage';
import Protected from './features/auth/component/Protected';
import { useEffect } from 'react';
import { fetchProductById } from './features/product/productListAPI';
import { fetchProductByIdAsync } from './features/product/productListSlice';
import { useDispatch, useSelector } from 'react-redux';
import { checkAuthAsync, selectloggedInUser, selectUserChecked } from './features/auth/authSlice';
import PageNotFound from './pages/404';
import OrderSuccessPage from './pages/OrderSuccessPage';
import UserOrderPage from './pages/UserOrderPage';
import UserProfilePage from './pages/UserProfilePage';
import { fetchLoggedInUserAsync, selectUserInfo } from './features/user/userSlice';
// import { updateUserAsync } from './features/auth/authSlice';
import Logout from './features/auth/component/Logout';
import ForgotPasswordPage from './pages/ForgotPasswordPage';
import AdminHome from './pages/AdminHome';
import ProtectedAdmin from './features/auth/component/ProtectedAdmin';
import AdminProductDetailPage from './pages/AdminProductDetailPage';
import ProductForm from './features/admin/component/ProductForm';
import AdminProductFormPage from './pages/AdminProductFormPage';
import AdminOrdersPage from './pages/AdminOrdersPage';
import { fetchItemsbyUserIdAsync } from './features/cart/cartSlice';
import StripeCheckout from './pages/StripeCheckout';
import { ToastContainer } from 'react-toastify';

function App() {

  const dispatch = useDispatch();
  const user = useSelector(selectloggedInUser);
  // console.log(user);
  const userChecked = useSelector(selectUserChecked)

  useEffect(() => {
    dispatch(checkAuthAsync())
  }, [dispatch])



  useEffect(() => {
    if (user) {
      dispatch(fetchItemsbyUserIdAsync())
      dispatch(fetchLoggedInUserAsync())

    }
  }, [dispatch, user])
  return (
    <div className="App">


      {userChecked && <BrowserRouter>
        <Routes>
          <Route path='/' element={<Protected><Home /></Protected>} /> //1
          <Route path='/admin' element={<ProtectedAdmin><AdminHome /></ProtectedAdmin>} /> //2

          <Route path='/login' element={<LoginPage />} />
          <Route path='/signup' element={<SignupPage />} />
          {/* ///only for test the cart */}
          {/* <Route path='/cart'  element={<Cart/>}/> */}
          <Route path='/cart' element={<Protected><CartPage /></Protected>} />
          <Route path='/checkout' element={<Protected><Checkout /></Protected>} />
          {/* /// it only for test  / */}
          {/* <Route path='/productDetail'  element={<ProductDetail/>}/> */}
          <Route path='/productDetail/:id' element={<Protected><ProductDetailPage /></Protected>} />
          {/* /////if we not apply protected then it show first page forex:- login page or click on Protected.js */}
          {/* ///////////////// */}

          <Route path='/admin/productDetail/:id' element={<ProtectedAdmin><AdminProductDetailPage /></ProtectedAdmin>} />

          {/* ////////////////// */}
          {/* //// */}
          <Route path='*' element={<PageNotFound />} /> ////// 404.js ///// path"*" it mean that ,you write any think on url then it will page is not found
          {/* <Route path='/order-success' element={<OrderSuccessPage />} /> */}
          <Route path='/order-success/:id' element={<OrderSuccessPage />} />
          {/* ////////////////////////
          //  */}
          <Route path='/orders' element={<UserOrderPage />} />
          {/* ////////////// we add page later right now using component directly */}

          <Route path='/profile' element={<Protected><UserProfilePage /></Protected>} />
          <Route path='/stripe-checkout/' element={<Protected><StripeCheckout /></Protected>} />

          <Route path='/logout' element={<Logout />} />
          <Route path='/forgot-password' element={<ForgotPasswordPage />} />
          {/* <RouterProvider Route={Router}></RouterProvider> */}

          {/* /////// */}
          <Route path='/admin/product-form' element={<ProtectedAdmin><AdminProductFormPage /></ProtectedAdmin>} />
          <Route path='/admin/orders' element={<ProtectedAdmin><AdminOrdersPage /></ProtectedAdmin>} />

          <Route path='/admin/product-form/edit/:id' element={<ProtectedAdmin><AdminProductFormPage /></ProtectedAdmin>} />



        </Routes>
      </BrowserRouter>}
      <ToastContainer />
    </div>
  );
}

export default App;
