import React from 'react'
import { ITEM_PER_PAGE } from '../../app/constants';
import { ChevronLeftIcon, ChevronRightIcon } from '@heroicons/react/24/outline';

function Pagination({ handlepage, page, setPage, totalitem }) {
  const totalPages = Math.ceil(totalitem / ITEM_PER_PAGE)
  return (<>
    <div className="flex flex-1 justify-between sm:hidden">
      <div
        onClick={(e) => { handlepage(page > 1 ? page - 1 : page) }} ////it move page when you click on previous button

        href="#"
        className="relative inline-flex items-center rounded-md border border-white/10 bg-white/5 px-4 py-2 text-sm font-medium text-gray-600 hover:bg-white/10"
      >
        Previous
      </div>
      <div
        onClick={(e) => { handlepage(page < totalPages ? page + 1 : page) }}

        href="#"
        className="relative ml-3 inline-flex items-center rounded-md border border-white/10 bg-white/5 px-4 py-2 text-sm font-medium text-gray-600 hover:bg-white/10"
      >
        Next
      </div>
    </div>
    <div className="hidden sm:flex sm:flex-1 sm:items-center sm:justify-between">
      <div>
        <p className="text-sm text-gray-500">
          {/* /////{ items_perpage ,totalitem,page-1} */}
          Showing{''} <span className="font-medium">{(page - 1) * ITEM_PER_PAGE + 1}</span>{''}
          to{''}
          <span className="font-medium">{page * ITEM_PER_PAGE > totalitem ? totalitem : page * ITEM_PER_PAGE}</span> of{' '}
          <span className="font-medium">{totalitem}</span> results
        </p>
      </div>
      <div>
        <nav aria-label="Pagination" className="isolate inline-flex -space-x-px rounded-md">

          <div
            onClick={(e) => { handlepage(page > 1 ? page - 1 : page) }} ////it move page when you click on previous button

            className="relative inline-flex items-center rounded-l-md px-2 py-2 text-gray-400 inset-ring inset-ring-gray-700 hover:bg-white/5 focus:z-20 focus:outline-offset-0"
          >
            <span className="sr-only">Previous</span>
            <ChevronLeftIcon aria-hidden="true" className="size-5" />
          </div>
          {/* Current: "z-10 text-white focus-visible:outline-2 focus-visible:outline-offset-2 bg-indigo-500 focus-visible:outline-indigo-500", Default: "inset-ring focus:outline-offset-0 text-gray-200 inset-ring-gray-700 hover:bg-white/5" */}
          {/* ///////// */}
          {Array.from({ length: totalPages }).map(
            (el, index) => (

              <div
                onClick={(e) => handlepage(index + 1)}
                aria-current="page"
                //   ////if current value is same as index +1  then it active {`   `  },,,,, put a condition ${} active 


                className={`relative cursor-pointer z-10 inline-flex items-center 
                ${index + 1 === page ? 'bg-indigo-500 text-white' : 'text-gray-400'} px-4 py-2 text-sm font-semibold
            //    text-black focus:z-20 focus-visible:outline-2
            //    focus-visible:outline-offset-2 focus-visible:outline-indigo-500`}
              >
                {index + 1}
              </div>



            )

          )}
          {/* <a
            href="#"
            className="relative inline-flex items-center px-4 py-2 text-sm font-semibold text-gray-200 inset-ring inset-ring-gray-700 hover:bg-white/5 focus:z-20 focus:outline-offset-0"
          >
            2
          </a> */}
          <span className="relative inline-flex items-center px-4 py-2 text-sm font-semibold text-gray-400 inset-ring inset-ring-gray-700 focus:outline-offset-0">
            ...
          </span>

          <div
            onClick={(e) => { handlepage(page < totalPages ? page + 1 : page) }}
            href="#"
            className="relative inline-flex items-center rounded-r-md px-2 py-2 text-gray-400 inset-ring inset-ring-gray-700 hover:bg-white/5 focus:z-20 focus:outline-offset-0"
          >
            <span className="sr-only">Next</span>
            <ChevronRightIcon aria-hidden="true" className="size-5" />
          </div>
        </nav>
      </div>
    </div>

  </>);
}

export default Pagination