import React, { useEffect } from 'react'
import { useDispatch, useSelector } from 'react-redux';
import { fetchLoggedInUserOrderAsync, selectUserInfo, selectUserInfoStatus, selectUserOrders } from '../userSlice';
import { discountedPrice } from '../../../app/constants';
// import { selectUserInfo } from '../../auth/authSlice';


function UserOrders() {
    const dispatch = useDispatch();
    // const userInfo = useSelector(selectUserInfo)
    const orders = useSelector(selectUserOrders)
    const status = useSelector(selectUserInfoStatus)    

    // const address = order.selectedAddress.addresses[0];

    useEffect(() => {
        dispatch(fetchLoggedInUserOrderAsync()) /////////////////////////?
    }, [dispatch])
    return (
        <>
            <div>
                {orders && orders.map((order) => (
                    // <div className='text-white p-24 text-2xl'>
                    //     {/* {order.id} */}
                    // </div>
                    <div className="    ">


                        <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 mt-5 ">

                            <div className="border-t border-gray-200 px-4 py-6 sm:px-6 bg-white">
                                <h1 className="text-4xl font-bold tracking-tight text-gray-900 pb-5">
                                    Order : {order.id}

                                </h1>
                                <h3 className="text-xl font-bold tracking-tight text-red-600 pb-5">
                                    Order Status : {order.status}

                                </h3>

                                <div className="flow-root">
                                    <ul role="list" className="-my-6 divide-y divide-gray-200">
                                        {order.items.map((item) => (
                                            <li key={item.id} className="flex py-6">
                                                <div className="size-24 shrink-0 overflow-hidden rounded-md border border-gray-200">
                                                    <img alt={item.product.title} src={item.product.thumbnail} className="size-full object-cover" />
                                                </div>

                                                <div className="ml-4 flex flex-1 flex-col">
                                                    <div>
                                                        <div className="flex justify-between text-base font-medium text-gray-900">
                                                            <h3>
                                                                <a href={item.product.category}>{item.product.brand}</a>
                                                            </h3>

                                                            <p className="ml-4">${discountedPrice(item.product)}</p>
                                                        </div>
                                                        {/* <p className="mt-1 text-sm text-gray-500">{item.product.title}</p> */}
                                                        <h3>
                                                            <a href={item.product.id} className="mt-1 text-sm text-gray-500">{item.product.title}</a>
                                                        </h3>
                                                    </div>
                                                    <div className="flex flex-1 items-end justify-between text-sm">
                                                        <p className="text-gray-500 ">
                                                            <label htmlFor="Quantity"
                                                                className="inline me-4 text-sm/6 font-medium text-black">
                                                                Qty:{item.quantity}
                                                            </label>


                                                        </p>


                                                    </div>
                                                </div>
                                            </li>
                                        ))}
                                    </ul>
                                </div>
                            </div>


                            <div className="border-t border-gray-200 px-4 py-6 sm:px-6 bg-slate-200">
                                <div className="flex justify-between my-2 text-base font-medium text-gray-900">
                                    <p className='font-bold'>Subtotal</p>
                                    <p className='font-bold'>${order.totalAmount}</p>

                                    {/* <p>$262.00</p> */}
                                </div>
                                <div className="flex justify-between  my-2 text-base font-medium text-gray-900">
                                    <p>Total items in Cart</p>
                                    <p>{order.totalItems} items</p>

                                    {/* <p>$262.00</p> */}
                                </div>

                                <p className="mt-0.5 text-sm text-gray-500">Address :-</p>
                                {/* /////////////////////////////////////////// */}
                                <div
                                    className="flex justify-between gap-x-6 py-5">
                                    <div className="flex min-w-0 gap-x-4">

                                        <div className="min-w-0 flex-auto pl-4">
                                            <p className="text-sm/6 font-semibold text-black">{order.selectedAddress.name}</p>
                                            <p className="mt-1 truncate text-xs/5 text-black">{order.selectedAddress.Society}</p>
                                            <p className="mt-1 truncate text-xs/5 text-gray-400">{order.selectedAddress.phone}</p>
                                            <p className="mt-1 truncate text-xs/5 text-gray-400">{order.selectedAddress.email}</p>
                                            <p className="mt-1 truncate text-xs/5 text-gray-400">{order.selectedAddress.pincode}</p>

                                        </div>
                                    </div>
                                    <div className="hidden shrink-0 sm:flex sm:flex-col sm:items-end pr-4 text-sm pt-5">
                                        <p className="mt-1 truncate text-xs/5 text-gray-400">{order.selectedAddress.street}</p>
                                        <p className="mt-1 truncate text-xs/5 text-gray-400">{order.selectedAddress.city}</p>
                                        <p className="mt-1 truncate text-xs/5 text-gray-400">{order.selectedAddress.state}</p>

                                    </div>
                                </div>

                            </div>
                        </div>



                    </div>

                )
                )
                }
            </div>
        </>
    )
}

export default UserOrders