import { createAsyncThunk, createSlice } from '@reduxjs/toolkit';
// import { fetchallproduct  } from './ProductListAPI';
import { createProduct, fetchallproduct, fetchProductById, fetchBrand, fetchCategories, fetchproductByFilters, updateProduct, } from './productListAPI';


const initialState = {
  products: [],
  brand: [],////
  category: [],////
  status: 'idle',
  totalitem: 0,
  selectedProduct: null //// it show redux consol
};


export const fetchProductByIdAsync = createAsyncThunk( /////////  fetchproductById fromm api
  'product/fetchProductById ',
  async (id) => {
    const response = await fetchProductById(id);
    // The products we return becomes the `fulfilled` action payload
    return response.data;
  }
);


export const fetchproductByFiltersAsync = createAsyncThunk(
  'product/fetchproductByFilters',
  async ({ filter, sort, pagination, admin }) => {
    // console.log(pagination);

    const response = await fetchproductByFilters({ filter, sort, pagination, admin: true });
    // The products we return becomes the `fulfilled` action payload
    return response.data;
  }
);

////// make asyn function for brand 
export const fetchBrandAsync = createAsyncThunk(
  'product/fetchBrand ',
  async () => {
    const response = await fetchBrand();
    // The products we return becomes the `fulfilled` action payload
    return response.data;
  }
);

/////make asyn function for category
export const fetchCategoriesAsync = createAsyncThunk(
  'product/fetchCategories',
  async () => {
    const response = await fetchCategories();
    // The products we return becomes the `fulfilled` action payload
    return response.data;
  }
);
/////////////////////////////productform.js
export const createProductAsync = createAsyncThunk(
  'product/createProduct',
  async (product) => {
    const response = await createProduct(product);
    // The products we return becomes the `fulfilled` action payload
    return response.data;
  }
);
export const updateProductAsync = createAsyncThunk(
  'product/update',
  async (update) => {
    const response = await updateProduct(update);
    // The products we return becomes the `fulfilled` action payload
    return response.data;
  }
);











export const productListSlice = createSlice({
  name: 'product',
  initialState,
  // The `reducers` field lets us define reducers and generate associated actions
  reducers: {
    clearSelectedProduct: (state) => {
      state.selectedProduct = null;
    }
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchproductByFiltersAsync.pending, (state) => {
        state.status = 'loading';
      })
      .addCase(fetchproductByFiltersAsync.fulfilled, (state, action) => {
        state.status = 'idle';
        state.products = action.payload.products;
        state.totalitem = action.payload.totalitem;

      })
      //////brand
      .addCase(fetchBrandAsync.pending, (state) => {
        state.status = 'loading';
      })
      .addCase(fetchBrandAsync.fulfilled, (state, action) => {
        state.status = 'idle';
        state.brand = action.payload;
      })
      //////categroy 
      .addCase(fetchCategoriesAsync.pending, (state) => {
        state.status = 'loading';
      })
      .addCase(fetchCategoriesAsync.fulfilled, (state, action) => {
        state.status = 'idle';
        state.category = action.payload;
        /////if we not write a categroy then will not open or redux 
      })

      .addCase(fetchProductByIdAsync.pending, (state) => {
        state.status = 'loading';
      })
      .addCase(fetchProductByIdAsync.fulfilled, (state, action) => {
        state.status = 'idle';
        state.selectedProduct = action.payload;
        /////if we not write a categroy then will not open or redux 
      })

      // /  //////
      .addCase(createProductAsync.pending, (state) => {
        state.status = 'loading';
      })
      .addCase(createProductAsync.fulfilled, (state, action) => {
        state.status = 'idle';
        state.products.push(action.payload);
        ///////////////////productform.js 
      })
      .addCase(updateProductAsync.pending, (state) => {
        state.status = 'loading';
      })
      .addCase(updateProductAsync.fulfilled, (state, action) => {
        state.status = 'idle';
        const index = state.products.findIndex(
          product => product.id === action.payload.id)
        state.products[index] = action.payload;
      });

  },
});

export const { clearSelectedProduct } = productListSlice.actions;

export const selectallproduct = (state) => state.product.products;

export const selectBrand = (state) => state.product.brand; ////take name as per dat.json brand
export const selectCategories = (state) => state.product.category; ////take name as per dat.json category 

export const selecttotalitem = (state) => state.product.totalitem;
export const selectedProductById = (state) => state.product.selectedProduct  ///// it show on redux consol

export default productListSlice.reducer;
