export function fetchallproduct() {
  return new Promise(async (resolve) => {
    const response = await fetch('http://localhost:8080/products')
    const data = await response.json()
    console.log(data);

    resolve({ data })
  }
  )
}


export function fetchProductById(id) { ////////////////////////// productdetail.js  then go slice.js
  return new Promise(async (resolve) => {
    const response = await fetch('http://localhost:8080/products/' + id)
    const data = await response.json()
    resolve({ data })
  }
  )
}

export function createProduct(product) { ////////////////////////// productform.js
  return new Promise(async (resolve) => {
    const response = await fetch('http://localhost:8080/products/', {
      method: 'POST',
      body: JSON.stringify(product),
      headers: { 'content-type': 'application/json' }
    });
    const data = await response.json()
    resolve({ data });
  }
  )
}


export function updateProduct(update) {
  return new Promise(async (resolve) => {
    const response = await fetch('http://localhost:8080/products/' + update.id,
      {
        method: 'PATCH',
        body: JSON.stringify(update),
        headers: { 'content-type': 'application/json' }

      });
    const data = await response.json()
    resolve({ data })
  }
  )
}





export function fetchproductByFilters({filter, sort, pagination, admin}) {
  ///////filter object  
  ///// filter ={"category":["Beauty",frangrance]}
  // sort={_sort:"price",_order="desc"}
  ///pagination ={_price:1,_limit=10}     ////_page=1&_limit=10
  // TODO:on server we will support multi vzlue in filter
  // console.log({pagination});


  let queryString = '';
  for (let key in filter) {
    //last value of push 
    const catergoryValue = filter[key];
    if (catergoryValue.length) {

      const lastCatergoryValue = catergoryValue[catergoryValue.length - 1]
      queryString += `${key}=${lastCatergoryValue}&`

    }
    ////
    // queryString += `${key}=${filter[key]}&`
  }
  //  console.log(queryString);

  ///

  for (let key in sort) {
    queryString += `${key}=${sort[key]}&`
  }

  /////
  for (let key in pagination) {


    queryString += `${key}=${pagination[key]}&`
  }
  console.log(queryString);
  if (admin) {
    queryString += `admin=true`

  }



  return new Promise(async (resolve) => {
    const response = await fetch('http://localhost:8080/products?' + queryString)
    const data = await response.json()
    console.log(data);

    // it show all over item
    const totalitem = await response.headers.get('X-Total-Count')
    ////it feature of json server that we use 
    resolve({ data: { products: data, totalitem: +totalitem } })
  }
  )
}
